python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/app/output');import gen
q=np.array(gen.r.get_obs(cameras=['robot_base'],video='none').meta['proprio']['now'][6:13]);Rd=np.column_stack(([0.,1,0],[0.,0,1],[1.,0,0]));target=[.476,.006,.329]
seeds=[]
for q2 in [q[1],-.72,-1.0,0.0]:
 for q4 in [q[3],-.65,-1.0]:
  for q6 in [q[5],1.43,0.8]:
   s=q.copy();s[1]=q2;s[3]=q4;s[5]=q6;seeds.append(s)
sol=[]
for s in seeds:
 qt=gen.ik_position(s,target,Rd,iterations=200,damping=.06)
 p,R,*_=gen.fk(qt);score=np.linalg.norm(qt-q)
 sol.append((np.linalg.norm(p-target)+.1*np.linalg.norm(R-Rd),score,qt,p,R[:,2]))
for z in sorted(sol,key=lambda z:z[0])[:8]:print('err',round(z[0],3),'dqnorm',round(z[1],2),'q',np.round(z[2],2),'p',np.round(z[3],2),'z',np.round(z[4],2))
PY
